{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { Parser } from './parser.js'
import { Limiter } from './limiter.js'

async function main() {
  const args = process.argv.slice(2)

  // Validate argument
  if (args.length !== 1 || !['replay', 'summary'].includes(args[0])) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const mode = args[0]

  // Read stdin
  let input = ''
  for await (const chunk of process.stdin) {
    input += chunk
  }

  try {
    // Parse input
    const parser = new Parser(input)
    const config = parser.parse()

    // Create limiter
    const limiter = new Limiter(config)

    // Process events
    const results = limiter.processEvents(config.events)

    // Output results
    if (mode === 'replay') {
      for (const result of results) {
        if (result.allowed) {
          process.stdout.write(`${result.tick} ${result.key} allow\n`)
        } else {
          process.stdout.write(`${result.tick} ${result.key} deny ${result.policy}\n`)
        }
      }
    } else {
      // summary mode
      const stats = {}
      let totalAllowed = 0
      let totalDenied = 0

      for (const result of results) {
        if (!stats[result.key]) {
          stats[result.key] = { allowed: 0, denied: 0 }
        }
        if (result.allowed) {
          stats[result.key].allowed++
          totalAllowed++
        } else {
          stats[result.key].denied++
          totalDenied++
        }
      }

      // Output per-key stats in sorted order
      for (const key of Object.keys(stats).sort()) {
        const s = stats[key]
        process.stdout.write(`${key} allowed=${s.allowed} denied=${s.denied}\n`)
      }

      // Output totals
      process.stdout.write(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
    }

    process.exit(0)
  } catch (error) {
    process.stderr.write(error.message + '\n')
    process.exit(2)
  }
}

main().catch(err => {
  process.stderr.write('error: ' + err.message + '\n')
  process.exit(2)
})
"}

