{"file_path":"src/parser.js","content":"/**
 * Parser for the limiter configuration file format.
 */

const VALID_NAME_CHARS = /^[A-Za-z0-9_.\/:"-]+$/
const VALID_DECIMAL = /^[0-9]+$/

export class Parser {
  constructor(input) {
    this.input = input
    this.lines = []
    this.lineNum = 0
    this.buckets = {}
    this.windows = {}
    this.routes = {}
    this.events = []
    this.firstEventLine = null
  }

  error(lineNum, message) {
    throw new Error(`line ${lineNum}: ${message}`)
  }

  parse() {
    // Split input on newlines and drop trailing empty line from trailing newline
    let lines = this.input.split('\n')
    if (lines.length > 0 && lines[lines.length - 1] === '') {
      lines.pop()
    }

    // Process each line
    for (let i = 0; i < lines.length; i++) {
      const lineNum = i + 1
      let line = lines[i].trim()

      // Skip empty lines and comments
      if (!line || line.startsWith('#')) {
        continue
      }

      // Split on runs of whitespace
      const tokens = line.split(/\s+/)
      if (tokens.length === 0) continue

      const directive = tokens[0]

      if (directive === 'bucket') {
        this.parseBucket(lineNum, tokens)
      } else if (directive === 'window') {
        this.parseWindow(lineNum, tokens)
      } else if (directive === 'route') {
        this.parseRoute(lineNum, tokens)
      } else if (directive === 'event') {
        this.parseEvent(lineNum, tokens)
      } else {
        this.error(lineNum, `unknown directive ${directive}`)
      }
    }

    return {
      buckets: this.buckets,
      windows: this.windows,
      routes: this.routes,
      events: this.events
    }
  }

  parseBucket(lineNum, tokens) {
    if (this.firstEventLine) {
      this.error(lineNum, 'declarations must come before the first event')
    }

    if (tokens.length !== 5) {
      this.error(lineNum, 'expected bucket <name> <capacity> <refill> <per>')
    }

    const name = tokens[1]
    const capacity = tokens[2]
    const refill = tokens[3]
    const per = tokens[4]

    // Validate name
    if (!VALID_NAME_CHARS.test(name)) {
      this.error(lineNum, `invalid policy name ${name}`)
    }

    // Check for duplicate
    if (this.buckets[name] || this.windows[name]) {
      this.error(lineNum, `policy ${name} is declared twice`)
    }

    // Validate numbers
    if (!VALID_DECIMAL.test(capacity)) {
      this.error(lineNum, 'capacity must be an integer of at least 1')
    }
    if (!VALID_DECIMAL.test(refill)) {
      this.error(lineNum, 'refill must be an integer of at least 0')
    }
    if (!VALID_DECIMAL.test(per)) {
      this.error(lineNum, 'per must be an integer of at least 1')
    }

    const capNum = parseInt(capacity)
    const refillNum = parseInt(refill)
    const perNum = parseInt(per)

    if (capNum < 1) {
      this.error(lineNum, 'capacity must be an integer of at least 1')
    }
    if (refillNum < 0) {
      this.error(lineNum, 'refill must be an integer of at least 0')
    }
    if (perNum < 1) {
      this.error(lineNum, 'per must be an integer of at least 1')
    }

    this.buckets[name] = {
      capacity: capNum,
      refill: refillNum,
      per: perNum
    }
  }

  parseWindow(lineNum, tokens) {
    if (this.firstEventLine) {
      this.error(lineNum, 'declarations must come before the first event')
    }

    if (tokens.length !== 4) {
      this.error(lineNum, 'expected window <name> <limit> <span>')
    }

    const name = tokens[1]
    const limit = tokens[2]
    const span = tokens[3]

    // Validate name
    if (!VALID_NAME_CHARS.test(name)) {
      this.error(lineNum, `invalid policy name ${name}`)
    }

    // Check for duplicate
    if (this.buckets[name] || this.windows[name]) {
      this.error(lineNum, `policy ${name} is declared twice`)
    }

    // Validate numbers
    if (!VALID_DECIMAL.test(limit)) {
      this.error(lineNum, 'limit must be an integer of at least 0')
    }
    if (!VALID_DECIMAL.test(span)) {
      this.error(lineNum, 'span must be an integer of at least 1')
    }

    const limitNum = parseInt(limit)
    const spanNum = parseInt(span)

    if (limitNum < 0) {
      this.error(lineNum, 'limit must be an integer of at least 0')
    }
    if (spanNum < 1) {
      this.error(lineNum, 'span must be an integer of at least 1')
    }

    this.windows[name] = {
      limit: limitNum,
      span: spanNum
    }
  }

  parseRoute(lineNum, tokens) {
    if (this.firstEventLine) {
      this.error(lineNum, 'declarations must come before the first event')
    }

    if (tokens.length < 3) {
      this.error(lineNum, 'expected route <prefix> <policy>...')
    }

    const prefix = tokens[1]
    const policies = tokens.slice(2)

    // Validate prefix
    if (!VALID_NAME_CHARS.test(prefix)) {
      this.error(lineNum, `invalid route prefix ${prefix}`)
    }

    // Check for duplicate prefix
    if (this.routes[prefix]) {
      this.error(lineNum, `prefix ${prefix} is routed twice`)
    }

    // Validate all policies exist
    for (const policy of policies) {
      if (!this.buckets[policy] && !this.windows[policy]) {
        this.error(lineNum, `unknown policy ${policy}`)
      }
    }

    this.routes[prefix] = policies
  }

  parseEvent(lineNum, tokens) {
    if (!this.firstEventLine) {
      this.firstEventLine = lineNum
    }

    if (tokens.length !== 3) {
      this.error(lineNum, 'expected event <tick> <key>')
    }

    const tick = tokens[1]
    const key = tokens[2]

    // Validate tick
    if (!VALID_DECIMAL.test(tick)) {
      this.error(lineNum, 'tick must be an integer of at least 0')
    }

    // Validate key
    if (!VALID_NAME_CHARS.test(key)) {
      this.error(lineNum, `invalid key ${key}`)
    }

    const tickNum = parseInt(tick)

    // Check tick order
    if (this.events.length > 0 && tickNum < this.events[this.events.length - 1].tick) {
      this.error(lineNum, `tick ${tickNum} is before tick ${this.events[this.events.length - 1].tick}`)
    }

    this.events.push({
      tick: tickNum,
      key: key,
      lineNum: lineNum
    })
  }
}
"}

