{"file_path":"src/policies.js","content":"/**
 * Implementations of token bucket and sliding window policies.
 */

export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = {} // key -> { tokens, lastTick }
  }

  getState(key) {
    if (!this.states[key]) {
      // Initialize with full capacity and current tick
      this.states[key] = { tokens: this.capacity, lastTick: null }
    }
    return this.states[key]
  }

  advance(key, tick) {
    const state = this.getState(key)

    if (state.lastTick === null) {
      state.lastTick = tick
      return
    }

    if (tick > state.lastTick) {
      const elapsed = tick - state.lastTick
      // Add refill tokens per per ticks: (refill * elapsed) / per
      // Keep as fraction to avoid rounding
      state.tokens += (this.refill * elapsed) / this.per
      if (state.tokens > this.capacity) {
        state.tokens = this.capacity
      }
      state.lastTick = tick
    }
  }

  allow(key) {
    const state = this.getState(key)
    return state.tokens >= 1
  }

  record(key) {
    const state = this.getState(key)
    state.tokens -= 1
  }
}

export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = {} // key -> { ticks: [], lastTick }
  }

  getState(key) {
    if (!this.states[key]) {
      this.states[key] = { ticks: [], lastTick: null }
    }
    return this.states[key]
  }

  advance(key, tick) {
    const state = this.getState(key)
    state.lastTick = tick

    // Forget ticks at or before (tick - span)
    const cutoff = tick - this.span
    state.ticks = state.ticks.filter(t => t > cutoff)
  }

  allow(key) {
    const state = this.getState(key)
    return state.ticks.length < this.limit
  }

  record(key, tick) {
    const state = this.getState(key)
    state.ticks.push(tick)
  }
}
"}

