{"file_path":"src/policies.js","content":"/**
 * Implementations of token bucket and sliding window policies.
 *
 * The token bucket keeps its level as an exact rational: an integer count of
 * `1/per` token fragments, held in BigInt so no accumulation is ever rounded.
 */

export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = BigInt(capacity)
    this.refill = BigInt(refill)
    this.per = BigInt(per)
    this.full = this.capacity * this.per // level of a full bucket, in fragments
    this.states = new Map() // key -> { level: BigInt fragments, lastTick: BigInt }
  }

  state(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      // A key first reaching the bucket finds it full, as of this tick.
      state = { level: this.full, lastTick: BigInt(tick) }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.state(key, tick)
    const now = BigInt(tick)
    if (now > state.lastTick) {
      const elapsed = now - state.lastTick
      state.level += this.refill * elapsed
      if (state.level > this.full) state.level = this.full
      state.lastTick = now
    }
  }

  allows(key, tick) {
    // At least one whole token, that is `per` fragments.
    return this.state(key, tick).level >= this.per
  }

  record(key, tick) {
    this.state(key, tick).level -= this.per
  }
}

export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = BigInt(span)
    this.states = new Map() // key -> BigInt[] remembered ticks, ascending
  }

  state(key) {
    let ticks = this.states.get(key)
    if (ticks === undefined) {
      ticks = []
      this.states.set(key, ticks)
    }
    return ticks
  }

  advance(key, tick) {
    const ticks = this.state(key)
    const cutoff = BigInt(tick) - this.span
    // Forget every remembered tick at or before tick - span.
    let drop = 0
    while (drop < ticks.length && ticks[drop] <= cutoff) drop++
    if (drop > 0) ticks.splice(0, drop)
  }

  allows(key) {
    return this.state(key).length < this.limit
  }

  record(key, tick) {
    this.state(key).push(BigInt(tick))
  }
}
"}

