export class Limiter {
  constructor(config) {
    this.buckets = {}
    this.windows = {}
    this.routes = {}

    // Initialize bucket policies
    for (const [name, def] of Object.entries(config.buckets)) {
      this.buckets[name] = new TokenBucket(def.capacity, def.refill, def.per)
    }

    // Initialize window policies
    for (const [name, def] of Object.entries(config.windows)) {
      this.windows[name] = new SlidingWindow(def.limit, def.span)
    }

    // Store routes
    this.routes = config.routes
  }

  findRoute(key) {
    // Find the longest matching route prefix
    let longestPrefix = null
    let longestPolicies = null

    for (const [prefix, policies] of Object.entries(this.routes)) {
      if (key.startsWith(prefix)) {
        if (!longestPrefix || prefix.length > longestPrefix.length) {
          longestPrefix = prefix
          longestPolicies = policies
        }
      }
    }

    return longestPolicies
  }

  processEvents(events) {
    const results = []

    for (const event of events) {
      const route = this.findRoute(event.key)

      // If no route matches, always allow
      if (!route) {
        results.push({
          tick: event.tick,
          key: event.key,
          allowed: true
        })
        continue
      }

      // Get all policies for this route
      const policies = []
      for (const policyName of route) {
        if (this.buckets[policyName]) {
          policies.push({
            name: policyName,
            policy: this.buckets[policyName]
          })
        } else if (this.windows[policyName]) {
          policies.push({
            name: policyName,
            policy: this.windows[policyName]
          })
        }
      }

      // Advance all policies to the event's tick
      for (const p of policies) {
        p.policy.advance(event.key, event.tick)
      }

      // Check if all policies allow
      let deniedBy = null
      let allAllow = true

      for (const p of policies) {
        if (!p.policy.allow(event.key)) {
          allAllow = false
          deniedBy = p.name
          break
        }
      }

      if (allAllow) {
        // Record the event in all policies
        for (const p of policies) {
          if (this.buckets[p.name]) {
            p.policy.record(event.key)
          } else if (this.windows[p.name]) {
            p.policy.record(event.key, event.tick)
          }
        }
        results.push({
          tick: event.tick,
          key: event.key,
          allowed: true
        })
      } else {
        // Event is denied
        results.push({
          tick: event.tick,
          key: event.key,
          allowed: false,
          policy: deniedBy
        })
      }
    }

