{"file_path":"src/parser.js","content":"/**
 * Parser for the limiter configuration file format.
 */

// A name, a route prefix and an event key are one or more of these characters.
const VALID_WORD = /^[A-Za-z0-9_./:-]+$/
// An unsigned decimal integer, no sign, no leading zero unless exactly "0".
const VALID_INTEGER = /^(0|[1-9][0-9]*)$/

export class Parser {
  constructor(input) {
    this.input = input
    this.policies = new Map() // name -> definition
    this.routes = new Map() // prefix -> policy names
    this.events = []
    this.seenEvent = false
    this.lastTick = null // BigInt
  }

  error(lineNum, message) {
    throw new Error(`line ${lineNum}: ${message}`)
  }

  /** Validates an unsigned integer field with a lower bound, returning a BigInt. */
  integer(lineNum, text, field, least) {
    if (!VALID_INTEGER.test(text)) {
      this.error(lineNum, `${field} must be an integer of at least ${least}`)
    }
    const value = BigInt(text)
    if (value < BigInt(least)) {
      this.error(lineNum, `${field} must be an integer of at least ${least}`)
    }
    return value
  }

  parse() {
    // Split on newlines, dropping the empty tail a trailing newline leaves.
    const lines = this.input.split('\n')
    if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

    for (let i = 0; i < lines.length; i++) {
      const lineNum = i + 1
      const line = lines[i].trim()

      // Ignore blank lines and comments.
      if (line === '' || line.startsWith('#')) continue

      const tokens = line.split(/\s+/)

      switch (tokens[0]) {
        case 'bucket':
          this.parseBucket(lineNum, tokens)
          break
        case 'window':
          this.parseWindow(lineNum, tokens)
          break
        case 'route':
          this.parseRoute(lineNum, tokens)
          break
        case 'event':
          this.parseEvent(lineNum, tokens)
          break
        default:
          this.error(lineNum, `unknown directive ${tokens[0]}`)
      }
    }

    return { policies: this.policies, routes: this.routes, events: this.events }
  }

  requireDeclarationPhase(lineNum) {
    if (this.seenEvent) {
      this.error(lineNum, 'declarations must come before the first event')
    }
  }

  declare(lineNum, name, definition) {
    if (!VALID_WORD.test(name)) this.error(lineNum, `invalid policy name ${name}`)
    if (this.policies.has(name)) this.error(lineNum, `policy ${name} is declared twice`)
    this.policies.set(name, definition)
  }

  parseBucket(lineNum, tokens) {
    this.requireDeclarationPhase(lineNum)
    if (tokens.length !== 5) {
      this.error(lineNum, 'expected bucket <name> <capacity> <refill> <per>')
    }

    const [, name, capacity, refill, per] = tokens
    if (!VALID_WORD.test(name)) this.error(lineNum, `invalid policy name ${name}`)
    if (this.policies.has(name)) this.error(lineNum, `policy ${name} is declared twice`)

    const definition = {
      kind: 'bucket',
      capacity: this.integer(lineNum, capacity, 'capacity', 1),
      refill: this.integer(lineNum, refill, 'refill', 0),
      per: this.integer(lineNum, per, 'per', 1)
    }
    this.policies.set(name, definition)
  }

  parseWindow(lineNum, tokens) {
    this.requireDeclarationPhase(lineNum)
    if (tokens.length !== 4) {
      this.error(lineNum, 'expected window <name> <limit> <span>')
    }

    const [, name, limit, span] = tokens
    if (!VALID_WORD.test(name)) this.error(lineNum, `invalid policy name ${name}`)
    if (this.policies.has(name)) this.error(lineNum, `policy ${name} is declared twice`)

    const definition = {
      kind: 'window',
      limit: Number(this.integer(lineNum, limit, 'limit', 0)),
      span: this.integer(lineNum, span, 'span', 1)
    }
    this.policies.set(name, definition)
  }

  parseRoute(lineNum, tokens) {
    this.requireDeclarationPhase(lineNum)
    if (tokens.length < 3) this.error(lineNum, 'expected route <prefix> <policy>...')

    const prefix = tokens[1]
    const names = tokens.slice(2)

    if (!VALID_WORD.test(prefix)) this.error(lineNum, `invalid route prefix ${prefix}`)
    if (this.routes.has(prefix)) this.error(lineNum, `prefix ${prefix} is routed twice`)

    for (const name of names) {
      if (!this.policies.has(name)) this.error(lineNum, `unknown policy ${name}`)
    }

    this.routes.set(prefix, names)
  }

  parseEvent(lineNum, tokens) {
    this.seenEvent = true
    if (tokens.length !== 3) this.error(lineNum, 'expected event <tick> <key>')

    const [, tickText, key] = tokens
    const tick = this.integer(lineNum, tickText, 'tick', 0)
    if (!VALID_WORD.test(key)) this.error(lineNum, `invalid key ${key}`)

    // Ticks never go backwards across the file.
    if (this.lastTick !== null && tick < this.lastTick) {
      this.error(lineNum, `tick ${tick} is before tick ${this.lastTick}`)
    }
    this.lastTick = tick

    this.events.push({ tick, key })
  }
}
"}

