/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { Parser } from './parser.js'
import { Limiter } from './limiter.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exitCode = 2
}

function replayReport(results) {
  const out = []
  for (const result of results) {
    out.push(
      result.allowed
        ? `${result.tick} ${result.key} allow\n`
        : `${result.tick} ${result.key} deny ${result.policy}\n`
    )
  }
  return out.join('')
}

function summaryReport(results) {
  const stats = new Map()
  let allowed = 0
  let denied = 0

  for (const result of results) {
    let entry = stats.get(result.key)
    if (entry === undefined) {
      entry = { allowed: 0, denied: 0 }
      stats.set(result.key, entry)
    }
    if (result.allowed) {
      entry.allowed++
      allowed++
    } else {
      entry.denied++
      denied++
    }
  }

  const out = []
  const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  for (const key of keys) {
    const entry = stats.get(key)
    out.push(`${key} allowed=${entry.allowed} denied=${entry.denied}\n`)
  }
  out.push(`total allowed=${allowed} denied=${denied}\n`)
  return out.join('')
}

async function readStdin() {
  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  return Buffer.concat(chunks.map((c) => (typeof c === 'string' ? Buffer.from(c) : c))).toString(
    'utf8'
  )
}

async function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    fail('usage: cli.js replay|summary')
    return
  }
  const mode = args[0]

  const input = await readStdin()

  let results
  try {
    const config = new Parser(input).parse()
    results = new Limiter(config).processEvents(config.events)
  } catch (error) {
    fail(error.message)
    return
  }

  process.stdout.write(mode === 'replay' ? replayReport(results) : summaryReport(results))
}

main().catch((error) => {
  fail(error && error.message ? error.message : String(error))
})
"}

